// Package: Microsoft.Extensions.AI
// Generates embeddings for document chunks with error handling and cancellation support.

using Microsoft.Extensions.AI;

public sealed class DocumentEmbedder
{
    private readonly IEmbeddingGenerator<string, Embedding<float>> _generator;

    public DocumentEmbedder(IEmbeddingGenerator<string, Embedding<float>> generator)
    {
        _generator = generator ?? throw new ArgumentNullException(nameof(generator));
    }

    public async Task<IReadOnlyList<EmbeddingRecord>> EmbedAsync(
        IEnumerable<string> chunks,
        CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(chunks);

        var results = new List<EmbeddingRecord>();

        await foreach (var batch in _generator.GenerateAsync(chunks).WithCancellation(ct))
        {
            results.Add(new EmbeddingRecord
            {
                Text = batch.RawText ?? string.Empty,
                Vector = [.. batch.Vector],
                GeneratedAt = DateTimeOffset.UtcNow
            });
        }

        return results;
    }

    public async Task<IReadOnlyList<EmbeddingRecord>> EmbedAsync(
        string text,
        CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(text);

        var results = new List<EmbeddingRecord>();

        await foreach (var batch in _generator.GenerateAsync(text, ct))
        {
            results.Add(new EmbeddingRecord
            {
                Text = batch.RawText ?? string.Empty,
                Vector = [.. batch.Vector],
                GeneratedAt = DateTimeOffset.UtcNow
            });
        }

        return results;
    }
}

public sealed record EmbeddingRecord(string Text, ReadOnlyMemory<float> Vector, DateTimeOffset GeneratedAt);

